<script lang="ts">
  import { PRODUCTS, type CartItem, type Product } from "./data";
  import Header from "./Header.svelte";
  import Nav from "./Nav.svelte";
  import Catalog from "./Catalog.svelte";
  import CartView from "./CartView.svelte";
  import Footer from "./Footer.svelte";

  let products = $state<Product[]>(PRODUCTS.map((p) => ({ ...p })));
  let cart = $state<CartItem[]>([]);
  let tab = $state<"catalog" | "cart">("catalog");
  let count = $derived(cart.reduce((n, i) => n + i.qty, 0));

  function add(product: Product) {
    const stockProduct = products.find((p) => p.id === product.id);
    if (!stockProduct || stockProduct.stock <= 0) return;
    stockProduct.stock--;
    const found = cart.find((i) => i.product.id === product.id);
    if (found) found.qty++;
    else cart.push({ product: { ...product }, qty: 1 });
  }

  function changeQty(id: number, delta: number) {
    const stockProduct = products.find((p) => p.id === id);
    if (!stockProduct) return;
    if (delta > 0 && stockProduct.stock < delta) return;
    stockProduct.stock -= delta;
    cart = cart.map((i) => (i.product.id === id ? { ...i, qty: i.qty + delta } : i)).filter((i) => i.qty > 0);
  }

  function clear() {
    for (const item of cart) {
      const p = products.find((p) => p.id === item.product.id);
      if (p) p.stock += item.qty;
    }
    cart = [];
  }
</script>

