import { useState } from "react";
import { PRODUCTS, type CartItem, type Product } from "./data";
import Header from "./Header";
import Nav from "./Nav";
import Catalog from "./Catalog";
import CartView from "./CartView";
import Footer from "./Footer";

export default function App() {
  const [products, setProducts] = useState<Product[]>(PRODUCTS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [tab, setTab] = useState<"catalog" | "cart">("catalog");

  function adjustStock(id: number, delta: number) {
    setProducts(products.map((p) => (p.id === id ? { ...p, stock: p.stock + delta } : p)));
  }

  function add(product: Product) {
    const current = products.find((p) => p.id === product.id);
    if (!current || current.stock <= 0) return;
    adjustStock(product.id, -1);
    const found = cart.find((i) => i.product.id === product.id);
    if (found) setCart(cart.map((i) => (i.product.id === product.id ? { ...i, qty: i.qty + 1 } : i)));
    else setCart([...cart, { product, qty: 1 }]);
  }

  function changeQty(id: number, delta: number) {
    const current = products.find((p) => p.id === id);
    const item = cart.find((i) => i.product.id === id);
    if (!current || !item) return;
    if (delta > 0 && current.stock < delta) return;
    adjustStock(id, -delta);
    setCart(cart.map((i) => (i.product.id === id ? { ...i, qty: i.qty + delta } : i)).filter((i) => i.qty > 0));
  }

  function clear() {
    setProducts(
      products.map((p) => {
        const item = cart.find((i) => i.product.id === p.id);
        return item ? { ...p, stock: p.stock + item.qty } : p;
      })
    );
    setCart([]);
  }

  const count = cart.reduce((n, i) => n + i.qty, 0);

  return (
    <div className="flex flex-col gap-4 p-4">
      <Header count={count} />
      <Nav tab={tab} onChange={setTab} />
      {tab === "catalog" ? (
        <Catalog products={products} onAdd={add} />
      ) : (
        <CartView cart={cart} onChangeQty={changeQty} onClear={clear} />
      )}
      <Footer />
    </div>
  );
}

