import { useState } from "react";
import type { Product } from "./data";
import SearchBox from "./SearchBox";
import ProductCard from "./ProductCard";

export default function Catalog({ products, onAdd }: { products: Product[]; onAdd: (p: Product) => void }) {
  const [query, setQuery] = useState("");
  const [sorted, setSorted] = useState(false);
  const filtered = products.filter((p) => p.name.toLowerCase().includes(query.toLowerCase()));
  const shown = sorted ? [...filtered].sort((a, b) => a.price - b.price) : filtered;

  return (
    <div className="flex flex-col gap-2">
      <SearchBox value={query} onChange={setQuery} />
      <button
        type="button"
        onClick={() => setSorted((s) => !s)}
        aria-pressed={sorted}
        className={`self-start rounded border px-3 py-1 ${
          sorted ? "bg-blue-600 text-white" : "bg-white text-gray-800 hover:bg-gray-100"
        }`}
      >
        Ordenar por precio
      </button>
      <div className="grid grid-cols-3 gap-2">
        {shown.map((p) => (
          <ProductCard key={p.id} product={p} onAdd={() => onAdd(p)} />
        ))}
      </div>
      {shown.length === 0 && <span className="text-gray-500">Sin resultados</span>}
    </div>
  );
}

